'use client';
import { PiChat } from '../pi-chat/pi-chat';
import type { PiChatProps } from '../pi-chat/pi-chat';
import type { SharedChatController } from '@hachej/boring-ui-kit/shared-chat';
import type { SharedLabels } from './shared-labels';
import type { SharedViewOptions } from './text';
import { useSharedChatProps } from './use-shared-chat';
import { withChatPlugins } from '../pi-chat-plugins/chat-plugins';

export { useSharedChat, useSharedChatProps } from './use-shared-chat';
export type { SharedViewOptions, SharedTextOptions } from './text';
export { defaultSharedLabels } from './shared-labels';
export { frenchSharedLabels } from './shared-labels-fr';
export type { SharedLabels } from './shared-labels';
export { createSharedChat, createChannelSocket, createRoomSource, createFakeChannelSource, channelAvatarStates, cardActions, ChannelRequestError } from '@hachej/boring-ui-kit/shared-chat';
export type { RoomSource, RoomSourceOptions, RoomWords, Question } from '@hachej/boring-ui-kit/shared-chat';
export type { ChannelSource, ChannelEvent, ChannelMessage, Member, Conversation, Card, CardAction, Step, AvatarState, SharedChatController } from '@hachej/boring-ui-kit/shared-chat';

export interface SharedChatProps extends Omit<PiChatProps, 'controller'>, SharedViewOptions {
  readonly controller: SharedChatController;
  readonly participantLabels?: Partial<SharedLabels>;
}
/**
 * Optional composition. PiChat still owns the regular shell, draft, send and composer lifecycle. The composer defaults to WhatsApp's:
 * one `pill` row and, with `voiceMessage`, the microphone in Send's place while empty; `composerLayout` and `voiceReplacesSend` override.
 * `composerStart` puts an app control at the left edge of the composer, `tools` beside Send.
 */
export function SharedChat({ participantLabels, presence, steps, answerActions, footer, answerStyle, ...props }: SharedChatProps) {
  const composition = useSharedChatProps(props.controller, { locale: props.locale, labels: participantLabels, presence, steps, answerActions, footer, answerStyle });
  return <PiChat {...withChatPlugins({ ...props, ...composition })} controls={<>{composition.controls}{props.controls}</>} composerChips={<>{props.composerChips}{composition.composerChips}</>}
    composerLayout={props.composerLayout ?? composition.composerLayout} voiceReplacesSend={props.voiceReplacesSend ?? composition.voiceReplacesSend} />;
}

'use client';
import { useEffect, useMemo, useRef, useState, useSyncExternalStore } from 'react';
import type { ReactNode } from 'react';
import { UserIcon } from 'lucide-react';
import { useControllerPerConversation } from '@hachej/boring-ui-kit/chat-react';
import { createSharedChat } from '@hachej/boring-ui-kit/shared-chat';
import type { ChannelSource, Conversation, SharedChatController } from '@hachej/boring-ui-kit/shared-chat';
import type { PiChatProps } from '../pi-chat/pi-chat';
import type { ConversationsConfig, MentionsConfig } from '../pi-chat/config';
import { MentionPicker } from '../pi-chat-mentions/mention-menu';
import { Badge } from '@/components/ui/badge';
import { Button } from '@/components/ui/button';
import { ItemContent, ItemDescription, ItemMedia, ItemTitle } from '@/components/ui/item';
import { namedMember } from './names';
import { MemberAvatar, SharedMembers, ReplyQuote, sharedQuote } from './messages';
import { SharedTimeline } from './timeline';
import type { TimelineApi } from './timeline';
import { SharedTextProvider } from './text';
import type { SharedTextOptions } from './text';
import { defaultSharedLabels } from './shared-labels';
import { frenchSharedLabels } from './shared-labels-fr';

const subscribeNothing = () => () => {};
/** Explicit host composition through PiChat's generic transcript, composer and catalog seams. */
export function useSharedChatProps(controller: SharedChatController | undefined, options: SharedTextOptions = {}): Omit<PiChatProps, 'controller'> {
  const state = useSyncExternalStore(controller?.subscribe ?? subscribeNothing, () => controller?.getSnapshot(), () => controller?.getSnapshot());
  const api = useRef<TimelineApi | undefined>(undefined);
  const raw = state?.shared.members;
  // Plain names only: an id or a slug the host sent in a name's place never reaches the picker, a chip or a mention.
  const meId = state?.shared.me.id;
  const labels = { ...(options.locale === 'fr' ? frenchSharedLabels : defaultSharedLabels), ...options.labels };
  const nameOf = labels.sharedName, sharedMembers = labels.sharedMembers, sharedRole = labels.sharedRole;
  const members = useMemo(() => (raw ?? []).map(member => namedMember(member, nameOf)), [raw, nameOf]);
  const mentions = useMemo<MentionsConfig>(() => ({
    listLabel: sharedMembers, icon: <UserIcon aria-hidden="true" />, Picker: MentionPicker,
    label: id => members.find(member => member.id === id)?.name ?? namedMember({ id, name: id, kind: 'person' }, nameOf).name,
    search: async query => members.filter(member => member.id !== meId && member.name.toLowerCase().includes(query.toLowerCase()))
      .sort((a, b) => Number(b.kind === 'agent') - Number(a.kind === 'agent')).map(member => ({ path: member.id, label: member.name })),
    render: id => <Badge variant="secondary">@{(members.find(member => member.id === id) ?? namedMember({ id, name: id, kind: 'person' }, nameOf)).name}</Badge>,
    renderSent: id => {
      const member = members.find(member => member.id === id) ?? namedMember({ id, name: id, kind: 'person' }, nameOf);
      return <span data-testid="message-mention" data-path={id} className="inline-flex items-baseline gap-1 align-baseline font-medium"><span aria-hidden="true"><MemberAvatar member={member} compact interactive={false} /></span><span data-testid="mention-name">{member.name}</span></span>;
    },
    renderOption: item => {
      const member = members.find(member => member.id === item.path);
      const role = member ? sharedRole(member) : undefined;
      return <><ItemMedia variant="icon">{member ? <MemberAvatar member={member} compact interactive={false} indicator={false} /> : <UserIcon aria-hidden="true" />}</ItemMedia><ItemContent className="min-w-0"><ItemTitle>{item.label}</ItemTitle>{role && <ItemDescription className="m-0 truncate">{role}</ItemDescription>}</ItemContent></>;
    },
  }), [members, meId, nameOf, sharedMembers, sharedRole]);
  const wrap = (children: ReactNode) => <SharedTextProvider {...options}>{children}</SharedTextProvider>;
  return {
    locale: options.locale,
    timeline: { count: state?.shared.messages.length ?? 0,
      render: context => controller ? wrap(<SharedTimeline controller={controller} api={api} mentions={mentions} {...context} />) : null,
      afterSend: () => api.current?.reset() },
    controls: controller && options.presence !== false ? wrap(<SharedMembers controller={controller} />) : undefined,
    mentions,
    composerHeader: controller && state?.shared.replyTo ? wrap(<ReplyQuote targetId={state.shared.replyTo} quote={sharedQuote(state.shared, state.shared.replyTo, nameOf)} onReveal={id => api.current?.reveal(id)} onRemove={() => controller.setReplyTo(undefined)} />) : undefined,
    composerHasContent: Boolean(state?.shared.files.length),
    onPickFiles: files => { if (controller) controller.setFiles([...controller.getSnapshot().shared.files, ...files]); },
    composerChips: controller && wrap(state?.shared.files.map((file, index) => <Badge key={index} variant="secondary">{file.name}<Button variant="ghost" size="icon" aria-label={`Remove ${file.name}`} onClick={() => controller.setFiles(controller.getSnapshot().shared.files.filter((_, at) => at !== index))}><span aria-hidden="true">×</span></Button></Badge>)),
    renderConnectionError: error => error instanceof Error ? error.message : String(error),
    // WhatsApp's composer; a host spreading these props can still override either.
    composerLayout: 'pill', voiceReplacesSend: true,
  };
}

/** Owns only the adapters it creates; each adapter borrows the host source. `limit`: messages per history page read from the source (default 60). */
export function useSharedChat(source: ChannelSource, options: SharedTextOptions & { readonly limit?: number | undefined } = {}) {
  const [list, setList] = useState<{ source: ChannelSource; items: Conversation[] }>();
  const [selection, setSelection] = useState<{ source: ChannelSource; id: string }>();
  // A failure belongs to the source that raised it: another source starts clean.
  const [failure, setFailure] = useState<{ source: ChannelSource; message: string }>();
  const error = failure?.source === source ? failure.message : undefined;
  const items = list?.source === source ? list.items : [];
  const conversationId = selection?.source === source ? selection.id : items[0]?.id;
  useEffect(() => {
    let off = false;
    void source.conversations().then(items => { if (!off) setList({ source, items }); }, cause => { if (!off) setFailure({ source, message: String(cause) }); });
    return () => { off = true; };
  }, [source]);
  const principalId = source.me.id;
  const key = useMemo(() => conversationId === undefined ? undefined : { source, conversationId, principalId, limit: options.limit }, [source, conversationId, principalId, options.limit]);
  const selected = useControllerPerConversation({ key,
    create: () => createSharedChat(source, { conversationId: conversationId!, ...(options.limit === undefined ? {} : { limit: options.limit }) }),
  });
  const controller = selected.status === 'ready' ? selected.controller : undefined;
  const conversations: ConversationsConfig = { items, activeId: conversationId, loading: list?.source !== source, onSelect: id => setSelection({ source, id }) };
  const chat = useSharedChatProps(controller, options);
  return { controller, conversationId, conversations, error,
    chatProps: controller ? { ...chat, controller, conversations } : undefined,
    workspaceProps: { controller, conversationId, conversations, locale: options.locale, controls: chat.controls, chat },
  };
}

'use client';

import { useEffect, useRef, useState, useSyncExternalStore } from 'react';
import type { ComponentProps, ReactNode } from 'react';
import { cardActions, channelAvatarStates } from '@hachej/boring-ui-kit/shared-chat';
import type { Card as Request, ChannelMessage, SharedChatController, Member, SharedChatState } from '@hachej/boring-ui-kit/shared-chat';
import { CheckIcon, CircleIcon, CopyIcon, HammerIcon, PinIcon, ReplyIcon, SparkleIcon, Trash2Icon, XIcon } from 'lucide-react';
import { Avatar, AvatarFallback, AvatarGroup, AvatarGroupCount, AvatarImage } from '@/components/ui/avatar';
import { Badge } from '@/components/ui/badge';
import { Button } from '@/components/ui/button';
import { Drawer, DrawerContent, DrawerTitle } from '@/components/ui/drawer';
import { Separator } from '@/components/ui/separator';
import { Popover, PopoverContent, PopoverTrigger } from '@/components/ui/popover';
import { Tooltip, TooltipContent, TooltipTrigger } from '@/components/ui/tooltip';
import { copyText } from '../utils/utils';
import { usePhone } from '../utils/use-media';
import { BubbleTail, ClockSpacer, MessageClock as ChatMessageClock, clockRoom } from '../pi-chat/message';
export { BubbleTail, ClockSpacer, clockRoom };
import { useChatText, useSharedView } from './text';
import { agentKind, namedMember } from './names';
import { defaultSharedLabels } from './shared-labels';
import type { SharedLabels } from './shared-labels';

// Text shares one treatment across headings and muted bubbles; only AA-qualified default palette entries colour it.
const agentTones = [
  { token: 'chart-1', icon: 'text-chart-1', text: 'text-foreground' },
  { token: 'chart-2', icon: 'text-chart-2', text: 'text-foreground dark:text-chart-2' },
  { token: 'chart-3', icon: 'text-chart-3', text: 'text-chart-3' },
  { token: 'chart-4', icon: 'text-chart-4', text: 'text-foreground' },
  { token: 'chart-5', icon: 'text-chart-5', text: 'text-foreground' },
];
export function agentTone(member: Pick<Member, 'id' | 'kind'>) {
  if (member.kind !== 'agent') return undefined;
  let hash = 0;
  for (const character of member.id) hash = (Math.imul(hash, 31) + character.charCodeAt(0)) >>> 0;
  return agentTones[hash % agentTones.length];
}

const latestCard = (shared: SharedChatState, id: string) => shared.messages.findLast(message => message.author === id && message.card)?.card;
type NameOf = SharedLabels['sharedName'];
const unknown = new WeakMap<NameOf, Map<string, Member>>();
const memberOf = (shared: SharedChatState, id: string, nameOf: NameOf): Member => {
  const found = shared.members.find(member => member.id === id);
  if (found) return namedMember(found, nameOf);
  let guests = unknown.get(nameOf);
  if (!guests) { guests = new Map(); unknown.set(nameOf, guests); }
  let guest = guests.get(id);
  if (!guest) { guest = namedMember({ id, name: id, kind: 'person' }, nameOf); guests.set(id, guest); }
  return guest;
};
export function sharedQuote(shared: SharedChatState, id: string | undefined, nameOf: NameOf = defaultSharedLabels.sharedName) {
  const message = shared.messages.find(message => message.id === id);
  return message ? { message, author: memberOf(shared, message.author, nameOf) } : undefined;
}

/** Only https, `data:image/`, `blob:` and same-origin relative addresses load; anything else falls back to the initials. */
export function safeAvatarUrl(url: string | undefined): string | undefined {
  if (!url) return undefined;
  return /^(?:https:\/\/|data:image\/|blob:)/i.test(url) || /^\/(?![/\\])/.test(url) ? url : undefined;
}

/** People show initials; agents a clean sparkle glyph in their chart token. `indicator={false}` drops the card-state dot (the timeline). */
export function MemberAvatar({ member, card, interactive = true, size = 'default', compact = false, indicator = true, className }: { readonly className?: string | undefined; readonly member: Member; readonly card?: Request | undefined; readonly interactive?: boolean; readonly size?: ComponentProps<typeof Avatar>['size']; readonly compact?: boolean; readonly indicator?: boolean }) {
  const { labels } = useChatText();
  const phone = usePhone();
  const [open, setOpen] = useState(false);
  useEffect(() => {
    if (!open) return;
    const close = () => setOpen(false);
    document.addEventListener('scroll', close, true);
    return () => document.removeEventListener('scroll', close, true);
  }, [open]);
  const state = member.kind === 'agent' && card?.state && Object.hasOwn(channelAvatarStates, card.state) ? channelAvatarStates[card.state] ?? 'neutral' : 'neutral';
  const tone = state === 'blocked' ? 'text-destructive' : state === 'waiting' ? 'text-muted-foreground' : 'text-primary';
  const agent = agentTone(member);
  const avatarSrc = safeAvatarUrl(member.avatarUrl);
  const kind = agentKind(member);
  // Agents are a rounded square with a glyph, in the agents' colour (info); people are a circle with their initial.
  const avatar = <Avatar size={compact ? 'sm' : size} className={`${kind ? 'rounded-md after:rounded-md ' : ''}${className ?? ''}`} data-agent-kind={kind} data-agent-color={agent?.token} data-testid="member-avatar" role="img" aria-label={member.kind === 'agent' ? `${member.name}, ${labels.sharedAgent}` : member.name} data-state={state}>
    {avatarSrc && <AvatarImage src={avatarSrc} alt={member.name} />}
    <AvatarFallback className={kind ? 'rounded-md bg-info-soft text-info-soft-foreground' : undefined}>{kind === 'builder' ? <HammerIcon data-lucide="hammer" className={compact ? 'size-3' : 'size-3.5'} aria-hidden="true" />
      : member.kind === 'agent' ? <SparkleIcon data-lucide="sparkle" className={`${compact ? 'size-3' : 'size-3.5'} fill-current`} aria-hidden="true" /> : member.name.replace(/[()]/g, '').split(/\s+/).slice(0, 2).map(word => word[0]).join('').toUpperCase()}</AvatarFallback>
    {indicator && state !== 'neutral' && <span data-testid="avatar-indicator" data-state={state} className={`absolute right-0 bottom-0 ${tone}`}>
      <CircleIcon className="size-2 fill-current" aria-hidden="true" />
    </span>}
  </Avatar>;
  if (member.kind !== 'agent' || !card || !interactive) return avatar;
  const trigger = <span role="button" tabIndex={0} className="inline-flex shrink-0" data-testid={`agent-avatar-${member.id}`} data-state={state} aria-label={`${member.name}: ${card.line}`}>{avatar}</span>;
  return phone
    ? <Popover open={open} onOpenChange={setOpen}><PopoverTrigger nativeButton={false} render={trigger} /><PopoverContent data-testid="agent-state-popover" side="bottom" align="start" className="max-w-[calc(100vw-1rem)]">{card.line}</PopoverContent></Popover>
    : <Tooltip><TooltipTrigger render={trigger} /><TooltipContent>{card.line}</TooltipContent></Tooltip>;
}
function MemberBadge({ member }: { readonly member: Member }) {
  const { labels } = useChatText();
  return member.kind === 'admin' ? <Badge data-testid="author-badge" variant="secondary">{labels.sharedAdmin}</Badge> : null;
}
function Dot({ value }: { readonly value: SharedChatState['status'] | Member['presence'] }) {
  return <CircleIcon aria-hidden="true" className={`size-2 fill-current ${value === 'live' || value === 'here' ? 'text-primary' : value === 'offline' ? 'text-destructive' : 'text-muted-foreground'}`} />;
}

/** Mounted in the existing bar. The source owns membership and visibility, including the admin. */
export function SharedMembers({ controller }: { readonly controller: SharedChatController }) {
  const state = useSyncExternalStore(controller.subscribe, controller.getSnapshot, controller.getSnapshot);
  const { labels } = useChatText();
  const [open, setOpen] = useState(false);
  const phone = usePhone();
  const shared = state.shared;
  if (!shared) return null;
  const name = shared.status === 'live' ? labels.live : shared.status === 'reconnecting' ? labels.reconnecting : labels.sharedOffline;
  const content = <ul data-testid="member-list" className="m-0 flex min-w-0 list-none flex-col gap-3 p-4">
    {shared.members.map(member => namedMember(member, labels.sharedName)).map(member => <li key={member.id} data-member-id={member.id} className="flex min-w-0 items-center gap-2">
      <MemberAvatar member={member} card={latestCard(shared, member.id)} /><span className="min-w-0 flex-1 truncate">{member.name}</span>
      <Badge variant="secondary">{labels.sharedRole(member) ?? member.role ?? member.kind}</Badge>
      <span data-testid="presence" data-presence={member.presence ?? 'away'} role="img" aria-label={member.presence === 'here' ? labels.sharedHere : labels.sharedAway}><Dot value={member.presence} /></span>
    </li>)}
  </ul>;
  const stack = <AvatarGroup>{shared.members.slice(0, phone ? 1 : 3).map(member => namedMember(member, labels.sharedName)).map(member => <MemberAvatar key={member.id} member={member} card={latestCard(shared, member.id)} interactive={false} />)}<AvatarGroupCount>{shared.members.length}</AvatarGroupCount></AvatarGroup>;
  const trigger = <Button variant="ghost" data-testid="shared-members" aria-label={labels.sharedMemberCount(shared.members.length)} aria-haspopup="dialog" aria-expanded={open}>{stack}</Button>;
  return <div className="flex shrink-0 items-center gap-2">
    <span data-testid="shared-connection-announcement" className="sr-only" aria-live="polite" aria-atomic="true">{name}</span>
    {shared.status !== 'live' && <Tooltip><TooltipTrigger render={<span tabIndex={0} data-testid="shared-status" data-status={shared.status} role="img" aria-label={name}><Dot value={shared.status} /></span>} /><TooltipContent>{name}</TooltipContent></Tooltip>}
    {phone ? <><Button variant="ghost" data-testid="shared-members" aria-label={labels.sharedMemberCount(shared.members.length)} aria-haspopup="dialog" aria-expanded={open} onClick={() => setOpen(true)}>{stack}</Button>
      {open && <Drawer open onOpenChange={setOpen} showSwipeHandle><DrawerContent className="pi-chat max-h-[80dvh]"><div className="flex shrink-0 items-center justify-between p-4"><DrawerTitle>{labels.sharedMembers}</DrawerTitle><Button variant="ghost" size="icon" data-testid="shared-members-close" aria-label={labels.close} onClick={() => setOpen(false)}><XIcon aria-hidden="true" /></Button></div><div className="min-h-0 overflow-y-auto">{content}</div></DrawerContent></Drawer>}</>
      : <Popover open={open} onOpenChange={setOpen}><PopoverTrigger render={trigger} /><PopoverContent role="dialog" aria-label={labels.sharedMembers} align="end" className="max-w-[calc(100vw-1rem)]">{content}</PopoverContent></Popover>}
  </div>;
}

/** The chat's time inside a bubble, with the shared chat's own clock and date labels. */
export function MessageClock(props: Omit<ComponentProps<typeof ChatMessageClock>, 'text' | 'title'>) {
  const { labels } = useChatText();
  return <ChatMessageClock {...props} className="text-[0.6875rem]" text={labels.sharedClock(props.at)} title={labels.sharedTimestamp(props.at)} />;
}

/** The member's role line: the host's own `roleLabel`, else the labels' derivation from kind and role. */
export function useRoleLine(member: Member): string | undefined {
  const { labels } = useChatText();
  return member.roleLabel?.trim() || labels.sharedRole(member);
}

/**
 * Who spoke, above the first bubble of a run by someone else in a room of several people: a small avatar (a circle with the
 * initial for a person, a rounded square with a glyph for an agent) and the name. Its role shows only on tap (or keyboard).
 * `via`: the outside agent or app that posted with this person's account.
 */
export function AuthorName({ member, via }: { readonly member: Member; readonly via?: string | undefined }) {
  const role = useRoleLine(member);
  const { labels } = useChatText();
  const author = namedMember(member, labels.sharedName);
  const agent = agentKind(author) !== undefined;
  const name = <span data-testid="message-author" data-agent-color={agentTone(author)?.token} className={`min-w-0 truncate text-xs font-medium ${agent ? 'text-info' : 'text-muted-foreground'}`}>{author.name}</span>;
  return <div data-testid="message-author-row" className="flex min-h-5 min-w-0 items-center gap-1.5 pb-0.5">
    <MemberAvatar member={author} compact interactive={false} indicator={false} className="size-5 data-[size=sm]:size-5" />
    {role && !(via && agent)
      ? <Popover><PopoverTrigger nativeButton={false} render={<span role="button" tabIndex={0} data-testid="message-author-toggle" aria-label={`${author.name} · ${role}`} className="-my-3.5 inline-flex min-h-11 min-w-11 cursor-pointer items-center" />}>{name}</PopoverTrigger>
        <PopoverContent data-testid="message-role" side="top" align="start" className="w-auto max-w-[calc(100vw-2rem)]">{author.name} · {role}</PopoverContent></Popover>
      : name}
    {via && <ViaLine via={via} />}
    {!(via && agent) && <MemberBadge member={author} />}
  </div>;
}

/** « via Claude Code »: the outside agent or app that posted with a person's account. */
export function ViaLine({ via, className = '' }: { readonly via: string; readonly className?: string }) {
  const { labels } = useChatText();
  return <span data-testid="message-via" className={`min-w-0 truncate text-xs text-muted-foreground ${className}`}>{labels.sharedVia(via)}</span>;
}

/**
 * A request inside its bubble: one title line, one muted line with the time, and the choices as text buttons along the bottom
 * (« Try · Later »). The primary choice takes the theme's primary colour; no border box.
 */
export function RequestCard({ card, action, at, own = false }: { readonly card: Request; readonly action: (card: Request, actionId?: string) => Promise<void>; readonly at?: string | undefined; readonly own?: boolean }) {
  const { labels } = useChatText();
  const [busy, setBusy] = useState<string>(), [error, setError] = useState<string>();
  const actions = cardActions(card);
  const run = (id: string) => {
    setBusy(id); setError(undefined);
    void action(card, id).catch(error => setError(error instanceof Error ? error.message : labels.actionFailedShort)).finally(() => setBusy(undefined));
  };
  return <section data-testid="request-card" aria-label={card.title} className="flex min-w-0 flex-col text-start">
    <p data-testid="request-title" className="m-0 truncate font-medium">{card.title}</p>
    <div className="flex min-w-0 items-baseline gap-3">
      <p data-testid="request-line" className={`m-0 min-w-0 flex-1 truncate ${own ? 'opacity-80' : 'text-muted-foreground'}`}>{card.line}</p>
      {at && <MessageClock at={at} tone={own ? 'primary' : 'muted'} floating={false} />}
    </div>
    {error && <p role="alert" className="m-0 text-destructive">{error}</p>}
    {actions.length > 0 && <>
      <Separator className="mt-2" />
      <div role="group" aria-label={card.title} className="-mx-3 -mb-2 flex min-w-0">
        {actions.map((choice, index) => {
          const primary = (choice.variant ?? (index === 0 ? 'primary' : 'secondary')) === 'primary';
          return <span key={choice.id} className={`contents ${primary && !own ? 'text-primary' : ''}`}>
            <Button data-testid="request-action" data-action={choice.id} data-action-variant={primary ? 'primary' : 'secondary'} variant="ghost" className="min-h-11 min-w-0 flex-1"
              disabled={busy !== undefined} aria-busy={busy === choice.id || undefined} onClick={() => run(choice.id)}><span className="truncate">{choice.label}</span></Button>
          </span>;
        })}
      </div>
    </>}
  </section>;
}

/**
 * An agent's question to the room: the prompt, its choices as text buttons along the bottom (one tap answers) and, when free text is
 * allowed, a Reply that opens the composer on this message. A reply to the question answers it; once answered the choices go away.
 */
export function QuestionCard({ message, answer, onReply, own = false }: { readonly message: ChannelMessage; readonly answer: (question: ChannelMessage, text: string) => Promise<unknown>; readonly onReply: (id: string) => void; readonly own?: boolean }) {
  const { labels } = useChatText();
  const [busy, setBusy] = useState<string>(), [error, setError] = useState<string>();
  const question = message.question!;
  const run = (option: string) => {
    setBusy(option); setError(undefined);
    void answer(message, option).catch(error => setError(error instanceof Error ? error.message : labels.actionFailedShort)).finally(() => setBusy(undefined));
  };
  const open = !question.answered;
  return <section data-testid="question-card" data-answered={question.answered ? 'true' : undefined} aria-label={question.prompt} className="flex min-w-0 flex-col text-start">
    <div className="flex min-w-0 items-baseline gap-3">
      <p data-testid="question-prompt" className="m-0 min-w-0 flex-1 whitespace-pre-wrap">{question.prompt}</p>
      <MessageClock at={message.at} tone={own ? 'primary' : 'muted'} floating={false} />
    </div>
