/** The row around one bubble: the avatar slot in multi-person channels, Reply and Delete on hover, focus or long-press. */
export function SharedMessage({ shared, children, remove, canRemove, openFile, onReply }: {
  readonly shared: SharedItem; readonly children: ReactNode;
  /** Multi-person channel (kept for hosts passing it): the avatar now rides in the author row above a group's first bubble (AuthorName). */
  readonly avatars?: boolean;
  readonly remove?: ((message: ChannelMessage) => Promise<void>) | undefined;
  readonly canRemove?: ((message: ChannelMessage) => boolean) | undefined;
  readonly openFile?: ((path: string) => void) | undefined;
  readonly onReply?: ((messageId: string) => void) | undefined;
  readonly onReveal?: ((messageId: string) => void) | undefined;
}) {
  const { labels } = useChatText();
  const view = useSharedView();
  const [error, setError] = useState<string>();
  const [copied, setCopied] = useState(false);
  const copiedTimer = useRef<ReturnType<typeof setTimeout> | undefined>(undefined);
  useEffect(() => () => clearTimeout(copiedTimer.current), []);
  const [actionsOpen, setActionsOpen] = useState(false);
  const phone = usePhone();
  const element = useRef<HTMLDivElement>(null);
  const press = useRef<ReturnType<typeof setTimeout> | undefined>(undefined);
  const start = useRef<{ x: number; y: number } | undefined>(undefined);
  const cancelPress = () => { clearTimeout(press.current); start.current = undefined; };
  useEffect(() => cancelPress, []);
  useEffect(() => {
    if (!actionsOpen) return;
    const outside = (event: PointerEvent) => { if (event.target instanceof Node && !element.current?.contains(event.target)) setActionsOpen(false); };
    document.addEventListener('pointerdown', outside);
    return () => document.removeEventListener('pointerdown', outside);
  }, [actionsOpen]);
  const { message, author, own } = shared;
  const replyable = Boolean(onReply && ((author.kind === 'agent' && !message.via) || message.card));
  const removable = Boolean(remove && canRemove?.(message));
  // An answer: the app agent's own message (not a person's, not a card, not a host notice).
  const answer = !own && author.kind === 'agent' && !message.via && !message.card && message.kind !== 'system' && !message.removed;
  const plain = view.answerStyle === 'plain' && answer;
  const copyable = answer && Boolean(message.text) && view.answerActions?.includes('copy') === true;
  const copy = () => { void copyText(message.text ?? '').then(() => { setCopied(true); clearTimeout(copiedTimer.current); copiedTimer.current = setTimeout(() => setCopied(false), 1500); }, () => setError(labels.copyFailed)); };
  const footer = answer ? view.footer?.(message) : undefined;
  // In a plain answer the copy action is a visible text button under it; in a bubble it is an icon on hover with Reply and Delete.
  const copyInline = copyable && plain, copyOnHover = copyable && !plain;
  const actionable = !message.removed && (replyable || removable || copyOnHover);
  return <div ref={element} data-shared-message={message.id} data-own={own ? 'true' : undefined} className="group/shared-message relative flex min-w-0 flex-col"
    tabIndex={phone && actionable ? 0 : undefined} aria-keyshortcuts={phone && actionable ? 'Shift+F10' : undefined}
    onKeyDown={event => {
      if (!phone || !actionable) return;
      if (event.key === 'ContextMenu' || event.key === 'F10' && event.shiftKey) { event.preventDefault(); setActionsOpen(true); }
      if (event.key === 'Escape') { setActionsOpen(false); element.current?.focus(); }
    }}
    onPointerDown={event => {
      if (!phone || !actionable || event.pointerType !== 'touch' || event.target instanceof Element && event.target.closest('button, a, input, textarea, [role=button], [role=link]')) return;
      cancelPress(); start.current = { x: event.clientX, y: event.clientY };
      press.current = setTimeout(() => setActionsOpen(true), 400);
    }}
    onPointerMove={event => { if (start.current && (Math.abs(event.clientX - start.current.x) > 8 || Math.abs(event.clientY - start.current.y) > 8)) cancelPress(); }}
    onPointerUp={cancelPress} onPointerCancel={cancelPress}
    onContextMenu={event => { if (phone && actionable && event.target instanceof Element && !event.target.closest('button, a, input, textarea, [role=button], [role=link]')) { event.preventDefault(); setActionsOpen(true); } }}>
    <div className="flex min-w-0 items-end gap-2.5">
    <div data-testid="shared-message-content" className={`flex min-w-0 flex-1 flex-col gap-1${own ? ' [&>button]:self-end' : ''}`}>
    {message.removed ? <p className="m-0 text-sm text-muted-foreground italic">{labels.sharedRemoved}</p> : children}
    {!message.removed && message.attachments?.map(file => <Button key={file.path} variant="outline" disabled={!openFile} onClick={() => openFile?.(file.path)} className="max-w-full justify-start"><span className="truncate">{file.title ?? file.path}</span></Button>)}
    {(copyInline || footer) && <div data-testid="message-footer" className="flex min-w-0 flex-wrap items-center gap-x-3 text-xs text-muted-foreground">
      {copyInline && <Button variant="ghost" size="sm" data-testid="message-copy" onClick={copy}>{copied ? <CheckIcon data-icon="inline-start" aria-hidden="true" /> : <CopyIcon data-icon="inline-start" aria-hidden="true" />}{copied ? labels.copied : labels.copyResponse}</Button>}
      {footer}
    </div>}
    {error && <p role="alert">{error}</p>}
    </div></div>
    {actionable && <div data-testid="shared-message-actions" hidden={phone && !actionsOpen} className={`absolute ${own ? 'left-0' : 'right-0'} top-0 ${phone && !actionsOpen ? 'hidden' : 'flex'} items-center gap-1${phone ? '' : ' opacity-0 group-hover/shared-message:opacity-100 group-focus-within/shared-message:opacity-100'}`}>
      {copyOnHover && <Tooltip><TooltipTrigger render={<Button variant="ghost" size={phone ? 'icon' : 'icon-xs'} data-testid="message-copy" aria-label={copied ? labels.copied : labels.copyResponse} onClick={copy}>{copied ? <CheckIcon aria-hidden="true" /> : <CopyIcon aria-hidden="true" />}</Button>} /><TooltipContent>{copied ? labels.copied : labels.copyResponse}</TooltipContent></Tooltip>}
      {replyable && onReply && <Tooltip><TooltipTrigger render={<Button variant="ghost" size={phone ? 'icon' : 'icon-xs'} data-testid="shared-reply" aria-label={labels.sharedReply} onClick={() => { setActionsOpen(false); onReply(message.id); }}><ReplyIcon aria-hidden="true" /></Button>} /><TooltipContent>{labels.sharedReply}</TooltipContent></Tooltip>}
      {removable && remove && <Tooltip><TooltipTrigger render={<Button variant="ghost" size={phone ? 'icon' : 'icon-xs'} aria-label={labels.delete} onClick={() => { void remove(message).catch(error => setError(error instanceof Error ? error.message : labels.actionFailedShort)); }}><Trash2Icon aria-hidden="true" /></Button>} /><TooltipContent>{labels.delete}</TooltipContent></Tooltip>}
    </div>}
  </div>;
}

export interface SharedItem {
  readonly key: string; readonly message: ChannelMessage; readonly author: Member; readonly own: boolean; readonly first: boolean; readonly lastItem: boolean;
  /** The first message of a calendar day: a day pill goes before it. */
  readonly separator: boolean;
  /** A run of consecutive host notices (`kind: 'system'`), shown as one collapsed item; `message` is its latest line. */
  readonly system?: readonly ChannelMessage[] | undefined;
  readonly showSpinner: boolean; readonly latestCard: Request | undefined; readonly quote: ReturnType<typeof sharedQuote>;
}
const dayOf = (at: string) => { const date = new Date(at); return Number.isFinite(date.getTime()) ? date.toDateString() : at; };
/**
 * WhatsApp's grouping: one author (and `via`) within fifteen minutes on the same day is a group; host notices end a group and
 * collapse together. Each day starts with a day pill.
 */
export function sharedItems(shared: SharedChatState, nameOf: NameOf = defaultSharedLabels.sharedName): SharedItem[] {
  const working = new Map(shared.messages.filter(message => message.streaming).map(message => [message.author, message.id]));
  const groups: ChannelMessage[][] = [];
  for (const message of shared.messages) {
    const group = groups.at(-1), previous = group?.at(-1);
    const elapsed = previous ? Date.parse(message.at) - Date.parse(previous.at) : NaN;
    const sameDay = previous !== undefined && dayOf(previous.at) === dayOf(message.at);
    const system = message.kind === 'system';
    if (group && previous && sameDay && (system ? previous.kind === 'system'
      : previous.kind !== 'system' && previous.author === message.author && previous.via === message.via && elapsed >= 0 && elapsed <= 15 * 60_000)) group.push(message);
    else groups.push([message]);
  }
  // One pass for what every item reads, instead of a search through the whole thread per message.
  const cards = new Map<string, Request>(), byId = new Map<string, ChannelMessage>();
  for (const message of shared.messages) { byId.set(message.id, message); if (message.card) cards.set(message.author, message.card); }
  const quoteOf = (replyTo: string | undefined) => { const message = replyTo === undefined ? undefined : byId.get(replyTo); return message ? { message, author: memberOf(shared, message.author, nameOf) } : undefined; };
  return groups.flatMap((group, groupIndex): SharedItem[] => {
    const before = groups[groupIndex - 1]?.at(-1);
    const separator = !before || dayOf(before.at) !== dayOf(group[0]!.at);
    if (group[0]!.kind === 'system') {
      const message = group.at(-1)!;
      return [{ key: `shared:${group[0]!.id}`, message, author: memberOf(shared, message.author, nameOf), own: false, first: true, lastItem: true, separator, system: group,
        showSpinner: false, latestCard: undefined, quote: undefined }];
    }
    const lastItem = group.at(-1);
    return group.map((message, index): SharedItem => ({ key: `shared:${message.id}`, message, author: memberOf(shared, message.author, nameOf), own: message.author === shared.me.id,
      first: index === 0, lastItem: message === lastItem, separator: index === 0 && separator,
      showSpinner: working.get(message.author) === message.id, latestCard: cards.get(message.author), quote: quoteOf(message.replyTo) }));
  });
}

'use client';
import { Children, memo, useCallback, useEffect, useLayoutEffect, useMemo, useRef, useState, useSyncExternalStore } from 'react';
import type { ReactNode, RefObject } from 'react';
import type { SharedChatController } from '@hachej/boring-ui-kit/shared-chat';
import type { ChatFeatureProps } from '../pi-chat/session';
import type { MentionsConfig } from '../pi-chat/config';
import { MessageText } from '../pi-chat/message';
import { Markdown } from '../pi-chat-markdown/markdown';
import { PAGE_FIRST, PAGE_MORE, useRowChunks, useTranscript } from '../pi-chat/session';
import type { ChatPaging } from '../pi-chat/session';
import { TranscriptHistory } from '../pi-chat/history';
import { Message, MessageContent } from '@/components/ui/message';
import { Bubble, BubbleContent } from '@/components/ui/bubble';
import { Badge } from '@/components/ui/badge';
import { Button } from '@/components/ui/button';
import { MessageScroller, MessageScrollerViewport, MessageScrollerContent, MessageScrollerItem } from '@/components/ui/message-scroller';
import { showsAuthors, runHead } from './names';
import { AuthorName, BubbleTail, ClockSpacer, MessageClock, PinnedComment, QuestionCard, ReplyQuote, RequestCard, SharedMessage, SystemLines, ViaLine, clockRoom, sharedItems } from './messages';
import type { SharedItem } from './messages';
import { HostTrace } from './host-trace';
import { useChatText, useSharedView } from './text';

export interface TimelineApi { readonly reset: () => void; readonly reveal: (id: string) => void }
/**
 * WhatsApp's room: bubbles hug the bottom, a day pill starts each day, host notices collapse into one small line, and a
 * « ↓ 3 new messages » pill appears below the list (never over it) while the reader is scrolled up.
 */
export function SharedTimeline({ controller, api, focusComposer, openFile, mentions, pendingVoice, paging, targetLabel }: {
  readonly controller: SharedChatController; readonly api: RefObject<TimelineApi | undefined>;
  readonly focusComposer: () => void; readonly openFile?: ((path: string) => void) | undefined; readonly mentions: MentionsConfig; readonly pendingVoice?: ReactNode; readonly paging?: ChatPaging | undefined;
  readonly targetLabel?: ChatFeatureProps['targetLabel'];
}) {
  const state = useSyncExternalStore(controller.subscribe, controller.getSnapshot, controller.getSnapshot);
  const { labels, icons } = useChatText();
  const view = useSharedView();
  const items = useStableItems(useMemo(() => sharedItems(state.shared, labels.sharedName), [state.shared, labels.sharedName]));
  const connected = state.connection.kind === 'connected';
  const transcript = useTranscript(items, paging?.first ?? PAGE_FIRST, paging?.more ?? PAGE_MORE, { state: state.history, connected: !state.disposed && connected, load: controller.loadEarlier });
  const { stick, hidden } = transcript;
  const chunks = useRowChunks(useMemo(() => hidden ? items.slice(hidden) : items, [items, hidden]));
  const root = useRef<HTMLDivElement>(null);
  const [revealing, setRevealing] = useState<string>();
  // The last message the reader has seen at the bottom; what others posted after it while scrolled up is « new ».
  const latest = state.shared.messages.at(-1)?.id;
  const [seen, setSeen] = useState(latest);
  // eslint-disable-next-line react-hooks/set-state-in-effect -- marks the latest message seen once the reader is at the bottom, after commit; settles when equal
  useEffect(() => { if (stick.isAtBottom && seen !== latest) setSeen(latest); }, [stick.isAtBottom, latest, seen]);
  // The pill's row shows only once the reader scrolls up, so loading a room (which scrolls down) never shifts the list under a tap.
  const lastTop = useRef(0);
  const [scrolledUp, setScrolledUp] = useState(false);
  // eslint-disable-next-line react-hooks/set-state-in-effect -- reaching the bottom hides the pill's row once, after commit
  useEffect(() => { if (stick.isAtBottom) setScrolledUp(false); }, [stick.isAtBottom]);
  const seenAt = state.shared.messages.findIndex(message => message.id === seen);
  const unseen = stick.isAtBottom ? 0 : state.shared.messages.slice(seenAt + 1).filter(message => message.author !== state.shared.me.id).length;
  // The reader's own new message lands in view, wherever they were: on Send it is drawn at once (pending), and Send's own scroll
  // runs before that render. Its confirmation (same clientId) is the same message and does not scroll again.
  const mine = state.shared.messages.findLast(message => message.author === state.shared.me.id);
  const mineKey = mine ? mine.clientId ?? mine.id : undefined;
  const lastMine = useRef(mineKey);
  useLayoutEffect(() => {
    if (mineKey === lastMine.current) return;
    const fresh = lastMine.current !== undefined || mine?.pending;
    lastMine.current = mineKey;
    if (fresh && mine === state.shared.messages.at(-1)) { transcript.reset(); void stick.scrollToBottom('instant'); }
    // eslint-disable-next-line react-hooks/exhaustive-deps -- scrolls only when the reader's own latest message changes, not on every message or transcript object
  }, [mineKey]);
  useEffect(() => bindApi(api, { reset: () => { transcript.reset(); void stick.scrollToBottom('instant'); }, reveal: setRevealing }), [api, transcript, stick]);
  useEffect(() => {
    if (!revealing) return;
    const key = items.find(item => item.message.id === revealing || item.system?.some(line => line.id === revealing))?.key;
    if (key) {
      transcript.revealTo(key);
      const frame = requestAnimationFrame(() => {
        const parent = [...(root.current?.querySelectorAll<HTMLElement>('[data-shared-message]') ?? [])].find(element => element.dataset.sharedMessage === revealing);
        if (parent) { parent.scrollIntoView({ block: 'center', behavior: 'instant' }); setRevealing(undefined); }
      });
      return () => cancelAnimationFrame(frame);
    }
    if (state.history.kind === 'loading') return;
    if (state.history.kind === 'ready' && state.history.hasMore) void controller.loadEarlier().catch(() => setRevealing(undefined));
    // A message that is neither loaded nor further back in history cannot be revealed.
    // eslint-disable-next-line react-hooks/set-state-in-effect -- an unreachable target is dropped once, after commit
    else setRevealing(undefined);
    // eslint-disable-next-line react-hooks/exhaustive-deps -- runs per target, rows and history page; the transcript object and controller are rebuilt or stable and must not re-trigger a reveal
  }, [revealing, items, hidden, state.history]);
  const hasContent = items.length > 0 || Children.count(pendingVoice) > 0;
  // Names and avatars only where they tell people apart: two or more members besides the reader.
  const multi = showsAuthors(state.shared.members, state.shared.me.id, view.presence);
  const focus = useRef(focusComposer);
  useLayoutEffect(() => { focus.current = focusComposer; });
  const reply = useCallback((id: string) => { controller.setReplyTo(id); focus.current(); }, [controller]);
  const open = useRef(openFile);
  useLayoutEffect(() => { open.current = openFile; });
  const hasOpen = Boolean(openFile);
  const stableOpen = useMemo(() => hasOpen ? (path: string) => open.current?.(path) : undefined, [hasOpen]);
  return <MessageScroller>
    <MessageScrollerViewport ref={node => { root.current = node; stick.scrollRef(node); }} data-testid="transcript-scroll" aria-label={labels.messages} className="min-h-0 flex-1 scrollbar-thumb-border scrollbar-track-transparent"
      onScroll={event => { const top = event.currentTarget.scrollTop; if (top < lastTop.current - 4) setScrolledUp(true); lastTop.current = top; }}>
      {items.length > 0 && (hidden > 0 || state.history.kind === 'loading' || state.history.kind === 'error' || state.history.kind === 'ready' && state.history.hasMore) && <TranscriptHistory history={state.history} connected={!state.disposed && connected} onLoad={transcript.reveal} sentinelRef={transcript.sentinelRef} hidden={hidden} loaded={transcript.loaded} />}
      <div data-testid="transcript-bottom" className="mx-auto flex min-h-full w-full max-w-[720px] flex-col justify-end px-4 pt-4 pb-3 md:px-6">
        <MessageScrollerContent aria-label={labels.messages} aria-live="polite" data-testid="transcript" className="h-auto min-h-0 gap-0 [&>[data-local-voice]]:mt-3">
          {chunks.map((run, index) => <TimelineChunk key={run[0]!.key} items={run} top={index === 0} multi={multi} controller={controller} mentions={mentions} openFile={stableOpen} targetLabel={targetLabel} onReply={reply} onReveal={setRevealing} />)}
          {pendingVoice}
        </MessageScrollerContent>
      </div>
    </MessageScrollerViewport>
    {hasContent && !stick.isAtBottom && scrolledUp && <div data-testid="transcript-navigation" className="flex shrink-0 items-center justify-center py-1.5">
      <Button variant="secondary" size="sm" data-testid="jump-latest" data-unseen={unseen || undefined} aria-label={unseen ? labels.sharedNewMessages(unseen) : labels.jumpToLatest} title={labels.jumpToLatest} className="max-md:min-h-11 pointer-coarse:min-h-11" onClick={() => api.current?.reset()}>
        <icons.jumpToLatest data-icon="inline-start" aria-hidden="true" />{unseen ? labels.sharedNewMessages(unseen) : labels.jumpToLatest}</Button>
    </div>}
  </MessageScroller>;
}

/** Same item, field by field (the quote is rebuilt each pass, so it compares by what it points at). */
const sameItem = (a: SharedItem, b: SharedItem) => a.key === b.key && a.message === b.message && a.author === b.author && a.own === b.own && a.first === b.first
  && a.lastItem === b.lastItem && a.separator === b.separator && a.showSpinner === b.showSpinner && a.latestCard === b.latestCard
  && a.quote?.message === b.quote?.message && a.quote?.author === b.quote?.author
  && (a.system === b.system || (a.system?.length === b.system?.length && a.system!.every((line, index) => line === b.system![index])));
/**
 * Keeps the previous object of every item that did not change, so a page loaded above, a delta or a new message renders only the
 * rows it touches (rows and their runs are memoized by identity).
 */
function useStableItems(next: readonly SharedItem[]): readonly SharedItem[] {
  // A derived identity cache, read and replaced inside the memo only: the same items always give the same objects.
  const previous = useRef(new Map<string, SharedItem>());
  return useMemo(() => {
    // eslint-disable-next-line react-hooks/refs -- reuses the cached object of an unchanged item; no setState, no render loop
    const items = next.map(item => { const before = previous.current.get(item.key); return before && sameItem(before, item) ? before : item; });
    // eslint-disable-next-line react-hooks/refs -- stores the items for the next pass; a cache write, not state, so it triggers no render
    previous.current = new Map(items.map(item => [item.key, item]));
    return items;
  }, [next]);
}

/** Hands the timeline's controls to the host's ref until this timeline unmounts or rebinds. */
function bindApi(api: RefObject<TimelineApi | undefined>, value: TimelineApi) {
  api.current = value;
  return () => { if (api.current === value) api.current = undefined; };
}

type RowProps = {
  readonly multi: boolean; readonly controller: SharedChatController; readonly mentions: MentionsConfig;
  readonly openFile: ((path: string) => void) | undefined; readonly targetLabel: ChatFeatureProps['targetLabel']; readonly onReply: (id: string) => void; readonly onReveal: (id: string) => void;
};
/** A run of timeline rows as one scroller item (`useRowChunks`). Memoized, like each row: it renders again only when its own items change. */
const TimelineChunk = memo(function TimelineChunk({ items, top, ...props }: RowProps & { readonly items: readonly SharedItem[]; readonly top: boolean }) {
  return <MessageScrollerItem messageId={items[0]!.key} data-transcript-chunk="" className="flex flex-col [content-visibility:visible] [gap:inherit]">
    {items.map((item, index) => <TimelineRow key={item.key} item={item} top={top && index === 0} {...props} />)}
  </MessageScrollerItem>;
});
const TimelineRow = memo(function TimelineRow({ item, top, multi, controller, mentions, openFile, targetLabel, onReply, onReveal }: RowProps & { readonly item: SharedItem; readonly top: boolean }) {
  const { labels } = useChatText();
  const view = useSharedView();
  const context = useMemo(() => ({ pieces: { mentions: true, skills: [], renderMention: mentions.renderSent }, openFile, targetLabel }), [mentions.renderSent, openFile, targetLabel]);
  const renderMention = (path: string, text: string) => mentions.renderSent?.(path) ?? text;
  const bubble = () => {
    const { message, author, own, first } = item;
    const person = own || author.kind !== 'agent' || message.via !== undefined;
    const headKind = runHead({ first, own, authors: multi, via: message.via });
    const head = headKind === 'author' ? <AuthorName member={author} via={message.via} /> : undefined;
    const traced = view.steps !== 'hidden' && !message.via && author.kind === 'agent' && Boolean(message.streaming || message.steps?.length);
    // Who spoke (and via what) sits above the group's first bubble, outside it: the bubble keeps its width. My own messages carry no name;
    // one posted through an outside agent says so on my side.
    const via = headKind === 'via' && message.via ? <ViaLine via={message.via} className="ms-auto block w-fit max-w-full pb-0.5 pe-1" /> : undefined;
    const live = traced && Boolean(message.streaming);
    const trace = traced ? <HostTrace participant={author.name} steps={message.steps ?? []} streaming={Boolean(message.streaming)} active={item.showSpinner} /> : undefined;
    const quote = message.replyTo ? <ReplyQuote targetId={message.replyTo} quote={item.quote} onReveal={onReveal} /> : undefined;
    if (message.question) return <article data-row-id={item.key} data-role="event" className="flex w-full min-w-0 flex-col">
      {head}{via}
      <Bubble variant="muted" align="start" data-testid="question-bubble">
        {first && <BubbleTail side="start" />}
        <BubbleContent className="relative min-w-52">{quote}
          <QuestionCard message={message} answer={controller.answer} onReply={onReply} />
        </BubbleContent>
      </Bubble></article>;
    if (message.card) return <article data-row-id={item.key} data-role="event" className="flex w-full min-w-0 flex-col">
      {head}{via}
      <Bubble variant={own ? 'default' : 'muted'} align={own ? 'end' : 'start'} data-testid="card-bubble">
        {first && <BubbleTail side={own ? 'end' : 'start'} />}
        <BubbleContent className="relative min-w-52">{quote}
          {message.card.kind === 'pin' ? <PinnedComment card={message.card} own={own} at={message.at} /> : <RequestCard card={message.card} action={controller.action} at={message.at} own={own} />}
        </BubbleContent>
      </Bubble></article>;
    return <article data-row-id={item.key} data-role={person ? 'user' : 'assistant'} data-streaming={message.streaming ? 'true' : undefined} data-pending={message.pending ? 'true' : undefined} className="group/message">{head}{via}<Message align={own ? 'end' : 'start'}><MessageContent>
      {own ? <div data-testid="own-message" className="contents [&_[data-testid=message-mention]]:text-inherit">
        <MessageText text={message.text ?? ''} context={context} variant="default" decoration={first ? <BubbleTail side="end" /> : undefined} header={quote} footer={<><ClockSpacer /><MessageClock at={message.at} tone="primary" pending={message.pending} /></>} /></div>
        : view.answerStyle === 'plain' && !person ? <div data-testid="plain-answer" className="min-w-0">
          {quote}
          {message.text && <Markdown text={message.text} streaming={Boolean(message.streaming)} renderMention={renderMention} />}
          {traced && <HostTrace participant={author.name} steps={message.steps ?? []} streaming={Boolean(message.streaming)} active={item.showSpinner} />}
        </div>
        : <Bubble variant="muted">{first && <BubbleTail side="start" />}<BubbleContent className="relative">
          {quote}
          {/* While the agent writes, the working line sits above the growing text and the time waits for the answer: nothing under the text moves as it grows (B5). */}
          {live && trace}
          {message.text && <div className={traced ? undefined : clockRoom}><Markdown text={message.text} streaming={Boolean(message.streaming)} renderMention={renderMention} /></div>}
          {traced ? <>
            {!live && trace}
            {!live && <div className="flex justify-end"><MessageClock at={message.at} tone="muted" floating={false} /></div>}
          </> : <MessageClock at={message.at} tone="muted" />}
        </BubbleContent></Bubble>}
    </MessageContent></Message></article>;
  };
  const gap = top || item.separator ? '' : item.system || item.first ? ' mt-3' : ' mt-0.5';
  return <div data-row-key={item.key} data-group-start={item.first ? 'true' : undefined} className={`min-w-0 shrink-0${gap}`}>
    {item.separator && <div data-testid="day-separator" className={`flex justify-center pb-3${top ? '' : ' pt-4'}`}><Badge variant="secondary"><time dateTime={item.message.at} title={labels.sharedTimestamp(item.message.at)}>{labels.sharedDay(item.message.at)}</time></Badge></div>}
    {item.system ? <SystemLines lines={item.system} />
      : <SharedMessage shared={item} remove={controller.remove} canRemove={controller.canRemove} openFile={openFile} onReply={onReply} onReveal={onReveal}>{bubble()}</SharedMessage>}
  </div>;
});

'use client';
import { useEffect, useState } from 'react';
import { AlertCircleIcon, CheckIcon, WrenchIcon } from 'lucide-react';
import type { Step } from '@hachej/boring-ui-kit/shared-chat';
import { Spinner } from '@/components/ui/spinner';
import { Trace, TraceCollapsible, TraceCollapsibleContent, TraceCollapsibleTrigger, TraceIcon, TraceLine, TraceTitle } from '@/components/ui/trace';
import { useChatText } from './text';

/** Host observations only. This trace neither creates Pi tool calls nor runs work. */
export function HostTrace({ steps, participant, streaming, active }: { readonly steps: readonly Step[]; readonly participant: string; readonly streaming: boolean; readonly active: boolean }) {
  const { labels } = useChatText();
  const [chosen, setChosen] = useState<boolean | undefined>();
  // Another participant or a run that starts or ends drops the reader's choice.
  // eslint-disable-next-line react-hooks/set-state-in-effect -- resets the choice once per participant or run change, after commit
  useEffect(() => setChosen(undefined), [participant, streaming]);
  const open = chosen ?? false;
  const state = streaming ? 'running' : steps.some(step => step.status === 'failed') ? 'failed' : 'done';
  const running = steps.reduce((found, step, index) => found === -1 && step.status === 'running' ? index : found, -1);
  const current = steps[running];
  const progress = current ? ` · ${current.label} (${running + 1}/${steps.length})` : '';
  const Icon = streaming ? Spinner : state === 'failed' ? AlertCircleIcon : CheckIcon;
  return <Trace data-testid="activity" data-boring="activity" data-state={state} data-open={open ? 'true' : 'false'} className="my-1.5">
    <TraceCollapsible open={open} onOpenChange={setChosen}>
      <TraceCollapsibleTrigger className="min-h-8 max-md:min-h-11 pointer-coarse:min-h-11">
        <TraceLine {...(streaming ? { status: 'running' } : state === 'failed' ? { status: 'error' } : {})}>
          {!(open || streaming && !active) && <TraceIcon><Icon aria-hidden="true" /></TraceIcon>}
          <TraceTitle data-testid="activity-label">{streaming ? `${labels.sharedWorking(participant)}${progress}` : labels.steps(steps.length)}</TraceTitle>
        </TraceLine>
      </TraceCollapsibleTrigger>
      <TraceCollapsibleContent><Trace data-testid="activity-steps">
        {steps.map((step, index) => {
          const StepIcon = step.status === 'running' ? open && active && streaming && index === running ? Spinner : WrenchIcon : step.status === 'done' ? CheckIcon : AlertCircleIcon;
          return <div key={index} data-testid="activity-step" data-kind="host" data-status={step.status === 'done' ? 'completed' : step.status}>
            <TraceLine data-testid="host-step" {...(step.status === 'running' ? { status: 'running' } : step.status === 'failed' ? { status: 'error' } : {})}>
              <TraceIcon><StepIcon aria-hidden="true" /></TraceIcon><TraceTitle><div className="flex min-w-0 flex-col"><span>{step.label}</span>{step.detail && <pre data-testid="step-detail" className="m-0 text-xs font-mono whitespace-pre-wrap text-muted-foreground [overflow-wrap:anywhere]">{step.detail}</pre>}</div></TraceTitle>
            </TraceLine>
          </div>;
        })}
      </Trace></TraceCollapsibleContent>
    </TraceCollapsible>
  </Trace>;
}

'use client';
import { createContext, useContext, useMemo } from 'react';
import type { ReactNode } from 'react';
import type { ChannelMessage } from '@hachej/boring-ui-kit/shared-chat';
import { useChatText as useNativeText, useShallowStable } from '../pi-chat/labels';
import { defaultSharedLabels } from './shared-labels';
import type { SharedLabels } from './shared-labels';
import { frenchSharedLabels } from './shared-labels-fr';

/** How the room looks. Every default is today's look; a host turns pieces off or on to match its own plain chat chrome. */
export interface SharedViewOptions {
  /** `false`: no members control, no avatars and no author lines. Default `true`. */
  readonly presence?: boolean | undefined;
  /** `'hidden'`: the agent's steps are never shown (no « 3 steps » line, no progress). Default `'shown'`. */
  readonly steps?: 'shown' | 'hidden' | undefined;
  /** Actions on an answer; `'copy'` copies its text. Default none. */
  readonly answerActions?: readonly 'copy'[] | undefined;
  /** A line under each answer (« Generated in 1.0 s »). Keep it stable (memoised or module-level): an inline function changes the view on every render. */
  readonly footer?: ((message: ChannelMessage) => ReactNode) | undefined;
  /** `'plain'`: the agent's answer is plain text, not a bubble; people's messages keep theirs. Default `'bubble'`. */
  readonly answerStyle?: 'bubble' | 'plain' | undefined;
}
export interface SharedTextOptions extends SharedViewOptions { readonly locale?: 'en' | 'fr' | undefined; readonly labels?: Partial<SharedLabels> | undefined }
const Context = createContext(defaultSharedLabels);
const View = createContext<SharedViewOptions>({});
export function SharedTextProvider({ children, locale, labels: given, presence, steps, answerActions: actions, footer, answerStyle }: SharedTextOptions & { readonly children: ReactNode }) {
  // Inline `labels` or `answerActions` keep one context while their content is the same (see useShallowStable).
  const labels = useShallowStable(given), answerActions = useShallowStable(actions);
  const value = useMemo(() => ({ ...(locale === 'fr' ? frenchSharedLabels : defaultSharedLabels), ...labels }), [locale, labels]);
  const view = useMemo<SharedViewOptions>(() => ({ presence, steps, answerActions, footer, answerStyle }), [presence, steps, answerActions, footer, answerStyle]);
  return <Context.Provider value={value}><View.Provider value={view}>{children}</View.Provider></Context.Provider>;
}
export const useSharedView = () => useContext(View);
export function useChatText() {
  const native = useNativeText(), labels = useContext(Context);
  return useMemo(() => ({ ...native, labels: { ...native.labels, ...labels } }), [native, labels]);
}

import type { Member } from '@hachej/boring-ui-kit/shared-chat';
import { defaultSharedLabels } from './shared-labels';
import type { SharedLabels } from './shared-labels';

/** The kinds of agent a thread tells apart: the app's assistant, the builder, any other. The words come from the labels (`sharedName`). */
export type AgentKind = 'assistant' | 'builder' | 'agent';

/** An id or a slug where a name should be (`agent:pm`, `user_1f3a…`, a uuid): never shown. */
const rawLike = (text: string) => /^[\w.-]+:[\w:.-]+$/.test(text) || /^[0-9a-f]{8}-[0-9a-f]{4}-/i.test(text) || /^(?:user|usr|agent|person)[_-][\w-]+$/i.test(text);

export function agentKind(member: Pick<Member, 'id' | 'kind' | 'role'>): AgentKind | undefined {
  if (member.kind !== 'agent') return undefined;
  const words = `${member.role ?? ''} ${member.id}`.toLowerCase().split(/[^a-z0-9]+/);
  // The room names its builder agent `worker` (`agent:worker`).
  if (words.includes('builder') || words.includes('build') || words.includes('worker')) return 'builder';
  if (words.includes('pm') || words.includes('assistant')) return 'assistant';
  return 'agent';
}

/** What a member is called in a thread: plain words, never an id. The assistant and the builder read as their role (`sharedName`). */
export function memberName(member: Pick<Member, 'id' | 'name' | 'kind' | 'role'>, words: SharedLabels['sharedName'] = defaultSharedLabels.sharedName): string {
  const kind = agentKind(member);
  if (kind === 'assistant' || kind === 'builder') return words(kind);
  const name = member.name?.trim();
  if (name && name !== member.id && !rawLike(name)) return name;
  return words(member.kind === 'agent' ? 'agent' : 'person');
}

const named = new WeakMap<SharedLabels['sharedName'], WeakMap<Member, Member>>();
/** The member with its display name; the same object for the same member (rows compare authors by identity). */
export function namedMember(member: Member, words: SharedLabels['sharedName'] = defaultSharedLabels.sharedName): Member {
  let cache = named.get(words);
  if (!cache) { cache = new WeakMap(); named.set(words, cache); }
  const found = cache.get(member);
  if (found) return found;
  const name = memberName(member, words);
  const result = name === member.name ? member : { ...member, name };
  cache.set(member, result);
  return result;
}

/** Names and avatars show only where they tell people apart: two or more members besides the reader (solo or a pair keeps the plain look). */
export function showsAuthors(members: readonly Pick<Member, 'id'>[], meId: string, presence?: boolean): boolean {
  return presence !== false && members.filter(member => member.id !== meId).length >= 2;
}

/** What sits above the first bubble of a run: the author of someone else's (when authors show), the « via » line of my own posted through an outside agent. */
export function runHead(row: { readonly first: boolean; readonly own: boolean; readonly authors: boolean; readonly via?: string | undefined }): 'author' | 'via' | undefined {
  if (!row.first) return undefined;
  if (row.own) return row.via ? 'via' : undefined;
  return row.authors ? 'author' : undefined;
}

// Building an Intl.DateTimeFormat costs far more than formatting with one; every bubble's clock reuses the same few.
const formats = new Map<string, Intl.DateTimeFormat>();
function format(locale: string, options: Intl.DateTimeFormatOptions): Intl.DateTimeFormat {
  const key = `${locale}|${JSON.stringify(options)}`;
  let found = formats.get(key);
  if (!found) { found = new Intl.DateTimeFormat(locale, options); formats.set(key, found); }
  return found;
}

export function formatTimestamp(at: string, locale: string) {
  const date = new Date(at);
  if (!Number.isFinite(date.getTime())) return at;
  return `${format(locale, { weekday: 'short', day: 'numeric', month: 'short' }).format(date)}, ${format(locale, { hour: '2-digit', minute: '2-digit' }).format(date)}`;
}
/** The time inside a bubble (« 14:02 », « 2:02 PM »). */
export function formatClock(at: string, locale: string) {
  const date = new Date(at);
  return Number.isFinite(date.getTime()) ? format(locale, { hour: 'numeric', minute: '2-digit' }).format(date) : '';
}
/** A day separator: today and yesterday by name, otherwise « Tue 22 Oct » (with the year when it is not this year). */
export function formatDay(at: string, locale: string, words: { readonly today: string; readonly yesterday: string }, now = Date.now()) {
  const date = new Date(at);
  if (!Number.isFinite(date.getTime())) return at;
  const start = (time: number) => { const day = new Date(time); day.setHours(0, 0, 0, 0); return day.getTime(); };
  const days = Math.round((start(now) - start(date.getTime())) / 86_400_000);
  if (days === 0) return words.today;
  if (days === 1) return words.yesterday;
  const sameYear = new Date(now).getFullYear() === date.getFullYear();
  return format(locale, { weekday: 'short', day: 'numeric', month: 'short', ...(sameYear ? {} : { year: 'numeric' }) }).format(date).replace(/,/g, '');
}
type RoleOf = { readonly kind: 'person' | 'agent' | 'admin'; readonly role?: string | undefined };
/** owner, validator and member read as themselves; every agent is the app's agent; the admin keeps its badge instead. */
export function roleLine(member: RoleOf, words: { readonly owner: string; readonly validator: string; readonly member: string; readonly agent: string }): string | undefined {
  if (member.kind === 'admin' || member.role === 'admin') return undefined;
  if (member.kind === 'agent' || member.role?.startsWith('agent:')) return words.agent;
  return member.role === 'owner' || member.role === 'validator' || member.role === 'member' ? words[member.role] : undefined;
}
export const defaultSharedLabels = {
  /** The full date and time, as the tooltip of a bubble's time. */
  sharedTimestamp: (at: string) => formatTimestamp(at, 'en'),
  /** The time inside a bubble, bottom right. */
  sharedClock: (at: string) => formatClock(at, 'en'),
  /** The centred day pill before the first message of each day. */
  sharedDay: (at: string) => formatDay(at, 'en-GB', { today: 'Today', yesterday: 'Yesterday' }),
  sharedNewMessages: (count: number) => count === 1 ? '1 new message' : `${count} new messages`,
  sharedMoreUpdates: (count: number) => count === 1 ? '1 more update' : `${count} more updates`, sharedFewerUpdates: 'Show less',
  sharedPinned: 'Pinned comment',
  sharedMembers: 'Members', sharedMemberCount: (count: number) => `${count} members`,
  /** What a thread calls someone with no usable name: the app's assistant, the builder, another agent, a person. Never an id. */
  sharedName: (who: 'assistant' | 'builder' | 'agent' | 'person') => ({ assistant: 'Your assistant', builder: 'Builder', agent: 'An agent', person: 'A teammate' })[who],
  sharedAgent: 'Agent', sharedVia: (name: string) => `via ${name}`,
  sharedWorking: (name: string) => `${name} is working…`,
  sharedAnswered: 'Answered', sharedReply: 'Reply', sharedCancelReply: 'Cancel reply', sharedEarlierMessage: 'Earlier message',
  sharedAdmin: 'Admin', sharedHere: 'Here', sharedAway: 'Away', sharedOffline: 'Offline',
  sharedRemoved: 'Message removed', sharedSince: (time: string) => `Since ${time}`,
  /** The line beside an author (« Léa · member »). Return undefined for none; a member's own `roleLabel` wins. */
  sharedRole: (member: RoleOf): string | undefined => roleLine(member, { owner: 'owner', validator: 'validator', member: 'member', agent: 'the app\u2019s agent' }),
};
export type SharedLabels = typeof defaultSharedLabels;
